import java.util.Scanner;
public class FermatLittleTheorem {static boolean prime(int n){if(n<2)return false;for(int i=2;i<=n/i;i++)if(n%i==0)return false;return true;}public static void main(String[] args){Scanner sc=new Scanner(System.in);System.out.print("Enter a: ");long a=sc.nextLong();System.out.print("Enter p: ");int p=sc.nextInt();if(prime(p)){if(Math.floorMod(a,p)==0)System.out.println("Fermat's theorem requires p not to divide a for a^(p-1) ≡ 1 mod p.");else System.out.println(a+"^("+(p-1)+") is congruent to 1 modulo "+p);}else System.out.println(p+" is not prime; Fermat's little theorem does not apply.");}}
